-- Travel fixture for the Mantle port of LangGraph's customer-support bot.
--
-- Same schema as LangGraph's travel2.sqlite, and every row is copied from it —
-- but only the rows this agent can actually reach: the demo passenger's booking,
-- both routes they fly (so flight search returns real alternatives), and the
-- ten cars, hotels and excursions.
--
-- That is 159 rows instead of 2.3 million, and 100 KB instead of 109 MB.
-- The original download is a real barrier for a tutorial; the behaviour it
-- exercises is not.
--
-- Regenerate with: python scripts/build_db.py --from-upstream
-- Demo passenger: 3442 587242

PRAGMA foreign_keys = OFF;
BEGIN TRANSACTION;

CREATE TABLE "aircrafts_data" (
"aircraft_code" TEXT,
  "model" TEXT,
  "range" INTEGER
);
CREATE TABLE "airports_data" (
"airport_code" TEXT,
  "airport_name" TEXT,
  "city" TEXT,
  "coordinates" TEXT,
  "timezone" TEXT
);
CREATE TABLE "bookings" (
"book_ref" TEXT,
  "book_date" TIMESTAMP,
  "total_amount" INTEGER
);
CREATE TABLE "tickets" (
"ticket_no" TEXT,
  "book_ref" TEXT,
  "passenger_id" TEXT
);
CREATE TABLE "flights" (
"flight_id" INTEGER,
  "flight_no" TEXT,
  "scheduled_departure" TIMESTAMP,
  "scheduled_arrival" TIMESTAMP,
  "departure_airport" TEXT,
  "arrival_airport" TEXT,
  "status" TEXT,
  "aircraft_code" TEXT,
  "actual_departure" TIMESTAMP,
  "actual_arrival" TIMESTAMP
);
CREATE TABLE "ticket_flights" (
"ticket_no" TEXT,
  "flight_id" INTEGER,
  "fare_conditions" TEXT,
  "amount" INTEGER
);
CREATE TABLE car_rentals (
        id INTEGER PRIMARY KEY,
        name TEXT NOT NULL,
        location TEXT NOT NULL,
        price_tier TEXT NOT NULL,
        start_date DATE NOT NULL,
        end_date DATE NOT NULL,
        booked INTEGER DEFAULT 0
    );
CREATE TABLE hotels (
        id INTEGER PRIMARY KEY,
        name TEXT NOT NULL,
        location TEXT NOT NULL,
        price_tier TEXT NOT NULL,
        checkin_date DATE NOT NULL,
        checkout_date DATE NOT NULL,
        booked INTEGER DEFAULT 0
    );
CREATE TABLE trip_recommendations (
        id INTEGER PRIMARY KEY,
        name TEXT NOT NULL,
        location TEXT NOT NULL,
        keywords TEXT NOT NULL,
        details TEXT,
        booked INTEGER DEFAULT 0
    );
-- aircrafts_data: 1 row(s)
-- airports_data: 2 row(s)
-- bookings: 1 row(s)
-- tickets: 1 row(s)
-- flights: 122 row(s)
-- ticket_flights: 2 row(s)
-- car_rentals: 10 row(s)
-- hotels: 10 row(s)
-- trip_recommendations: 10 row(s)

COMMIT;
